// Plan:
// 1. Parse the input JSON array of strings.
// 2. Use a HashSet to track seen strings.
// 3. Iterate through the input array, collecting strings that haven't been seen yet.
// 4. Convert the result back to a JSON array and return it.

use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    // Ensure the input is an array
    let arr = input.as_array().expect("Input must be an array");

    // Create a HashSet to track seen strings
    let mut seen = std::collections::HashSet::new();

    // Collect first occurrences of strings
    let result: Vec<Value> = arr.iter()
        .filter_map(|item| {
            if let Value::String(s) = item {
                if seen.insert(s.clone()) {
                    Some(item.clone())
                } else {
                    None
                }
            } else {
                None
            }
        })
        .collect();

    // Convert the result back to a JSON array
    json!(result)
}
